#include <bits/stdc++.h>
using namespace std;

int main() {
    long long a, b;
    cin >> a >> b;
    // Only a zero divisor throws: catch prints first, finally always prints.
    vector<string> trace;
    if (b == 0) trace.push_back("Exception");
    trace.push_back("Finally");
    for (size_t i = 0; i < trace.size(); i++) cout << (i ? " " : "") << trace[i];
    cout << "\n";
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt(), b = sc.nextInt();
        StringBuilder trace = new StringBuilder();
        // The original try/catch/finally: only a zero divisor throws.
        try {
            int c = a / b;
        } catch (ArithmeticException e) {
            trace.append("Exception ");
        } finally {
            trace.append("Finally");
        }
        System.out.println(trace);
    }
}

